import{_ as p,a0 as u,w as o,s as l,ao as s,I as i,x as t,a1 as r,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const w=JSON.parse('{"title":"每日Ubuntu小技巧：一款輕量級的Email閲讀器Geary | LCTT x X-CMD","titleTemplate":false,"description":"每日Ubuntu小技巧：一款輕量級的Email閲讀器Geary | LCTT (201311) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"每日Ubuntu小技巧：一款輕量級的Email閲讀器Geary | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"每日Ubuntu小技巧：一款輕量級的Email閲讀器Geary | LCTT (201311) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201311/Daily Ubuntu Tips – Get Geary, A Lightweight Email Reader In Ubuntu","title":"每日Ubuntu小技巧：一款輕量級的Email閲讀器Geary","tag":"201311","desc":""},"relativePath":"201311/Daily Ubuntu Tips – Get Geary, A Lightweight Email Reader In Ubuntu.md","filePath":"[post].md"}'),d={name:"201311/Daily Ubuntu Tips – Get Geary, A Lightweight Email Reader In Ubuntu.md"};function m(g,e,y,b,T,G){const a=u("Link");return o(),l("div",null,[e[11]||(e[11]=s(`<h1 id="每日ubuntu小技巧-一款輕量級的email閲讀器geary" tabindex="-1">每日Ubuntu小技巧：一款輕量級的Email閲讀器Geary <a class="header-anchor" href="#每日ubuntu小技巧-一款輕量級的email閲讀器geary" aria-label="Permalink to “每日Ubuntu小技巧：一款輕量級的Email閲讀器Geary”">​</a></h1><p>正如大家所知，Ubuntu 本身自帶可以收發郵件的客户端——Thunderbird，當然它也支持Gmail，Yahoo Mail，Microsoft Outlook 等等支持IMAP協議的郵件服務。</p><p>Thunderbird 是一個功能強大的郵件客户端，只要email客户端所需要的功能，它都能夠做到。但是如果你想選擇一個能在夠在GNOME 下運行的輕量級客户端，Geary 是一個不錯的選擇。</p><p>Geary 是一個界面簡潔，能讓你快捷方便的地閲讀郵件的免費程序。它所有的對話均展示在一個簡潔的面板上，這樣你可以不必點擊鼠標來切換消息。</p><p>Geary 還支持IMAP 協議，所以你可以使用Google, Yahoo 和 Microsoft 這樣的在線郵箱服務。</p><p>以Ubuntu 13.10用户為例，Geary 可以在Ubuntu 的軟件中心獲取。只要運行以下命令即可安裝Geary 。</p><pre><code>sudo apt-get install geary
</code></pre><p>在以前的Ubuntu 版本中，鍵盤按下<strong>Ctrl – Alt – T</strong> 可以打開終端。打開之後，運行以下命令增加PPA源。</p><pre><code>sudo add-apt-repository ppa:yorba/ppa
</code></pre><p>接下來運行以下命令來升級系統和安裝Geary 。</p><pre><code>sudo apt-get update &amp;&amp; sudo apt-get install geary
</code></pre><p>第一次啓動Geary時，你需要設置你的Gmail，Yahoo 或 Microsoft 電子郵件帳户。</p><p><img src="http://www.liberiangeek.net/wp-content/uploads/2013/11/gearyubuntu.png" alt=""></p><p>設置非常的簡單，只要輸入你的賬號信息，Geary 就會自動配置好你的賬號。</p><p>若想卸載Geary ，首先要從系統中移除它的PPA源，要運行的命令如下。</p><pre><code>sudo add-apt-repository -r ppa:yorba/ppa
</code></pre><p>然後再運行以下命令卸載Geary 。</p><pre><code>sudo apt-get remove geary 
</code></pre><p>就這麼簡單~</p><hr>`,20)),i("p",null,[e[1]||(e[1]=t("via: ",-1)),r(a,{href:"http://www.liberiangeek.net/2013/11/daily-ubuntu-tips-get-geary-a-lightweight-email-reader-in-ubuntu/"},{default:n(()=>[...e[0]||(e[0]=[t("http://www.liberiangeek.net/2013/11/daily-ubuntu-tips-get-geary-a-lightweight-email-reader-in-ubuntu/",-1)])]),_:1})]),i("p",null,[e[4]||(e[4]=t("譯者：",-1)),r(a,{href:"https://github.com/NearTan"},{default:n(()=>[...e[2]||(e[2]=[t("NearTan",-1)])]),_:1}),e[5]||(e[5]=t(" 校對：",-1)),r(a,{href:"https://github.com/carolinewuyan"},{default:n(()=>[...e[3]||(e[3]=[t("Caroline",-1)])]),_:1})]),i("p",null,[e[8]||(e[8]=t("本文由 ",-1)),r(a,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...e[6]||(e[6]=[t("LCTT",-1)])]),_:1}),e[9]||(e[9]=t(" 原創翻譯，",-1)),r(a,{href:"http://linux.cn/"},{default:n(()=>[...e[7]||(e[7]=[t("Linux中國",-1)])]),_:1}),e[10]||(e[10]=t(" 榮譽推出",-1))])])}const U=p(d,[["render",m]]);export{w as __pageData,U as default};
